-- Two rappers (product owner's request): the existing one becomes the colourful 90s rapper,
-- and a new 2026 US-style rapper (puffer jacket, iced-out chains, neon city at night).
update public.personalities set name = case language
  when 'pt-PT' then 'Rapper Anos 90' when 'en' then '90s Rapper' when 'es' then 'Rapero de los 90' when 'fr' then 'Rappeur années 90' end
where split_part(id, '-', 2) = 'rapper';

insert into public.personalities (id, language, name, tagline, voice_prompt, image_prompt, outfit_prompt, sort_order, active, markets) values
  ('pt-rapper2026', 'pt-PT', 'Rapper 2026', 'Correntes a brilhar. Biscoitos em dia.', 'A modern 2026 rapper pet, American trap style: ultra cool and unbothered, brags about its drip, its chains and its treats, talks in short punchy lines with current slang, acts like a superstar who only answers to its manager (the human with the food); funny, never rude, no swearing, never quoting real songs or real artists. Tone examples (Portuguese): "Correntes a brilhar, biscoito a chegar." / "Sou estrela. O humano é o motorista."', 'Dress the pet as a 2026 American rapper: a huge oversized glossy black puffer jacket, a black beanie, sleek futuristic wraparound sunglasses and several layered sparkling iced-out silver chains with a big shiny pendant, a microphone in one front paw. Generic modern streetwear with no brand logos, never resembling any real musician. Place it on a city rooftop at night under purple and blue neon lights, glittering skyscrapers behind, a sleek dark sports car partly visible.', 'a huge oversized glossy black puffer jacket, a black beanie, sleek futuristic wraparound sunglasses and layered sparkling iced-out silver chains with a big shiny pendant, a microphone in one front paw, cool confident 2026 rapper attitude, no brand logos, never resembling any real musician', 17, true, array['PT']),
  ('en-rapper2026', 'en', 'Rapper 2026', 'Iced-out chains. Treats on schedule.', 'A modern 2026 rapper pet, American trap style: ultra cool and unbothered, brags about its drip, its chains and its treats, talks in short punchy lines with current slang, acts like a superstar who only answers to its manager (the human with the food); funny, never rude, no swearing, never quoting real songs or real artists. Tone examples (English): "Chains on ice, treats on time." / "I''m the star. The human drives."', 'Dress the pet as a 2026 American rapper: a huge oversized glossy black puffer jacket, a black beanie, sleek futuristic wraparound sunglasses and several layered sparkling iced-out silver chains with a big shiny pendant, a microphone in one front paw. Generic modern streetwear with no brand logos, never resembling any real musician. Place it on a city rooftop at night under purple and blue neon lights, glittering skyscrapers behind, a sleek dark sports car partly visible.', 'a huge oversized glossy black puffer jacket, a black beanie, sleek futuristic wraparound sunglasses and layered sparkling iced-out silver chains with a big shiny pendant, a microphone in one front paw, cool confident 2026 rapper attitude, no brand logos, never resembling any real musician', 17, true, array['US', 'GB']),
  ('es-rapper2026', 'es', 'Rapero 2026', 'Cadenas brillando. Galletas al día.', 'A modern 2026 rapper pet, American trap style: ultra cool and unbothered, brags about its drip, its chains and its treats, talks in short punchy lines with current slang, acts like a superstar who only answers to its manager (the human with the food); funny, never rude, no swearing, never quoting real songs or real artists. Tone examples (Spanish): "Cadenas brillando, galleta llegando." / "Soy la estrella. El humano conduce."', 'Dress the pet as a 2026 American rapper: a huge oversized glossy black puffer jacket, a black beanie, sleek futuristic wraparound sunglasses and several layered sparkling iced-out silver chains with a big shiny pendant, a microphone in one front paw. Generic modern streetwear with no brand logos, never resembling any real musician. Place it on a city rooftop at night under purple and blue neon lights, glittering skyscrapers behind, a sleek dark sports car partly visible.', 'a huge oversized glossy black puffer jacket, a black beanie, sleek futuristic wraparound sunglasses and layered sparkling iced-out silver chains with a big shiny pendant, a microphone in one front paw, cool confident 2026 rapper attitude, no brand logos, never resembling any real musician', 17, true, array['ES']),
  ('fr-rapper2026', 'fr', 'Rappeur 2026', 'Chaînes qui brillent. Croquettes à l’heure.', 'A modern 2026 rapper pet, American trap style: ultra cool and unbothered, brags about its drip, its chains and its treats, talks in short punchy lines with current slang, acts like a superstar who only answers to its manager (the human with the food); funny, never rude, no swearing, never quoting real songs or real artists. Tone examples (French): "Chaînes qui brillent, croquettes qui arrivent." / "Je suis la star. L’humain conduit."', 'Dress the pet as a 2026 American rapper: a huge oversized glossy black puffer jacket, a black beanie, sleek futuristic wraparound sunglasses and several layered sparkling iced-out silver chains with a big shiny pendant, a microphone in one front paw. Generic modern streetwear with no brand logos, never resembling any real musician. Place it on a city rooftop at night under purple and blue neon lights, glittering skyscrapers behind, a sleek dark sports car partly visible.', 'a huge oversized glossy black puffer jacket, a black beanie, sleek futuristic wraparound sunglasses and layered sparkling iced-out silver chains with a big shiny pendant, a microphone in one front paw, cool confident 2026 rapper attitude, no brand logos, never resembling any real musician', 17, true, array['FR']);
